SELECT CASE WHEN departments.budget >= 3484000 THEN 'high' WHEN departments.budget >= 1091000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(employees.salary) AS total_salary, COUNT(DISTINCT employees.salary) AS unique_managers FROM employees LEFT JOIN departments ON employees.dept_id = departments.id WHERE employees.salary > 142000 GROUP BY CASE WHEN departments.budget >= 3484000 THEN 'high' WHEN departments.budget >= 1091000 THEN 'mid' ELSE 'low' END;
